ALTER TABLE content_items ADD COLUMN details JSONB NOT NULL DEFAULT '{}'::jsonb;

INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Bảo hiểm','Chuẩn bị hành trình an tâm với thông tin bảo hiểm. Bạn có thể chọn bảo hiểm demo trong booking và thanh toán qua luồng mua thêm dịch vụ hiện có.','/assets/services/insurance-banner.jpg','/services/insurance',9000,'{"heading":"Bảo hiểm du lịch Vietjet Travel Safe","provider":"Vietjet Travel Safe","source":"https://www.vietjetair.com/vi/insurance","steps":["Chọn booking đã xác nhận","Xem giá bảo hiểm nội bộ","Báo giá và thanh toán mua thêm"],"faq":[["Tôi có nhận chứng nhận bảo hiểm thật không?","Bảo hiểm nội bộ chỉ phục vụ trải nghiệm demo. Chứng nhận, điều khoản, hiệu lực và yêu cầu bồi thường thực tế phải được xác nhận với nhà cung cấp."],["Tôi chọn bảo hiểm cho ai và chặng nào?","Nút mua thêm chuyển tới quản lý booking và chọn trước dịch vụ cho hành khách có ghế đầu tiên, ở chặng đầu tiên. Bạn có thể đổi hành khách và chặng trước khi báo giá."],["Tôi mua bảo hiểm khi đặt vé mới thế nào?","Chọn chuyến bay và nhập hành khách; tại bước dịch vụ bổ sung, chọn bảo hiểm cho từng hành khách và chặng rồi tiếp tục thanh toán demo."]]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Mua ngoại tệ','Vietjet giới thiệu dịch vụ ngoại tệ cùng HDBank. Tra cứu booking nội bộ và gửi nhu cầu tư vấn cho chuyến đi của bạn.','/assets/services/currency-banner.jpg','/services/currency',9000,'{"heading":"Mua ngoại tệ cho chuyến đi","provider":"HDBank","source":"https://www.vietjetair.com/vi/currency-exchange","fields":[{"name":"currency","label":"Loại ngoại tệ","options":["USD","EUR","AUD","JPY","SGD"]},{"name":"amount","label":"Số tiền dự kiến","type":"number","min":1,"max":1000000,"step":1},{"name":"pickup","label":"Nơi nhận mong muốn"}],"steps":["Tra cứu mã đặt chỗ nội bộ","Gửi nhu cầu ngoại tệ","Xác nhận tỷ giá và nơi nhận với HDBank"],"faq":[["Tôi đã mua ngoại tệ khi gửi yêu cầu chưa?","Yêu cầu chỉ ghi nhận loại tiền, số tiền và nơi nhận mong muốn. Nhân viên trao đổi tại Trung tâm hỗ trợ; ngân hàng xác nhận điều kiện và giao dịch."],["Tôi có thể xem hướng dẫn gốc ở đâu?","Mở trang nhà cung cấp để xem hướng dẫn và điều kiện hiện hành. Việc tra cứu booking demo không xác nhận đủ điều kiện mua ngoại tệ tại ngân hàng."]],"guides":[{"title":"Mua ngoại tệ khi đặt chuyến bay","image":"/assets/services/currency-guide-1.jpg"},{"title":"Mua ngoại tệ từ Chuyến bay của tôi","image":"/assets/services/currency-guide-2.jpg"}]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','eVisa','Chuẩn bị thông tin quốc tịch, điểm đến và các chặng quá cảnh để nhận hướng dẫn trước chuyến đi.','/assets/services/visa-banner.png','/services/visa',9000,'{"heading":"Quy định xuất nhập cảnh","provider":"Sherpa","source":"https://apps.joinsherpa.io/trip?appId=spkzNTUxNz&language=vi-VN","fields":[{"name":"nationality","label":"Quốc tịch"},{"name":"destination","label":"Điểm đến"},{"name":"transit","label":"Điểm quá cảnh","required":false},{"name":"departure","label":"Ngày khởi hành","type":"date"}],"steps":["Chuẩn bị thông tin hành trình","Kiểm tra yêu cầu với Sherpa","Xác minh với cơ quan có thẩm quyền"],"faq":[["Tôi cần cung cấp hộ chiếu không?","Form tư vấn chỉ cần quốc tịch và hành trình. Hồ sơ, lệ phí và tiến độ cấp visa do nhà cung cấp hoặc cơ quan có thẩm quyền xử lý."],["Có cần kiểm tra yêu cầu tại điểm quá cảnh?","Hãy kiểm tra điều kiện của từng điểm quá cảnh và điểm đến. Quy định có thể thay đổi; sử dụng nguồn chính thức trước khi khởi hành."],["Gửi yêu cầu có đảm bảo được cấp visa không?","Quy định cần được kiểm tra với cơ quan có thẩm quyền; hệ thống nội bộ không xác nhận quyền nhập cảnh."]]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','eSIM','Chọn quốc gia, thời gian sử dụng và kiểm tra thiết bị trước chuyến đi. Gửi nhu cầu để nhận tư vấn trong tài khoản của bạn.','/assets/services/esim-banner.jpg','/services/esim',9000,'{"heading":"Bay khắp thế giới với eSIM","provider":"SkyFi","source":"https://agent.skyfi.vn/buy-esim/nations?language=vi","fields":[{"name":"country","label":"Quốc gia sử dụng"},{"name":"days","label":"Số ngày sử dụng","type":"number","min":1,"max":180,"defaultValue":"7"},{"name":"device","label":"Thiết bị sử dụng"},{"name":"compatible","label":"Thiết bị hỗ trợ eSIM","options":["Đã kiểm tra","Cần được hướng dẫn"]}],"steps":["Kiểm tra thiết bị và quốc gia","Chọn nhu cầu dữ liệu và thời gian","Nhận hướng dẫn kích hoạt từ SkyFi"],"faq":[["Làm sao kiểm tra thiết bị hỗ trợ eSIM?","Kiểm tra phần SIM trong cài đặt điện thoại và tài liệu của hãng. Thiết bị cần hỗ trợ eSIM và không bị khóa mạng."],["Tôi nhận mã QR ở đâu?","Nhà cung cấp cấp mã QR sau khi hoàn tất mua gói. Hệ thống nội bộ hiện nhận yêu cầu tư vấn; chưa bán gói hoặc cấp mã kích hoạt."],["Bản nháp eSIM có bị lẫn với khách sạn không?","Mỗi dịch vụ lưu bản nháp riêng trong phiên trình duyệt. Yêu cầu đã gửi được lưu trong tài khoản và có thể theo dõi tại Trung tâm hỗ trợ."]]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Khách sạn','Lên kế hoạch nghỉ dưỡng, chọn điểm đến và gửi nhu cầu lưu trú cho đội ngũ hỗ trợ.','/assets/reference/hotel.webp','/services/hotels',9000,'{"heading":"Khách sạn cho hành trình của bạn","provider":"Agoda","source":"https://www.agoda.com/vi-vn/vietjetair?ds=SGA3IfaG1eLf0S4v","fields":[{"name":"destination","label":"Điểm đến"},{"name":"checkIn","label":"Ngày nhận phòng","type":"date"},{"name":"checkOut","label":"Ngày trả phòng","type":"date"},{"name":"rooms","label":"Số phòng","type":"number","min":1,"max":20,"defaultValue":"1"},{"name":"guests","label":"Số khách","type":"number","min":1,"max":60,"defaultValue":"2"}],"steps":["Chọn điểm đến và thời gian lưu trú","Gửi yêu cầu và theo dõi tư vấn","Kiểm tra phòng, giá và điều kiện tại Agoda"],"faq":[["Tôi đã đặt phòng sau khi gửi yêu cầu chưa?","Yêu cầu tư vấn được lưu trong hệ thống nội bộ. Xác nhận phòng, thanh toán và hủy phòng cần thực hiện với nhà cung cấp."],["Tôi theo dõi yêu cầu ở đâu?","Mở Trung tâm hỗ trợ để xem phản hồi, bổ sung thông tin hoặc đóng yêu cầu."]]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','SkyJoy','Chương trình nội bộ dành cho trải nghiệm demo. Banner giới thiệu chương trình của đối tác; ví bên dưới sử dụng điểm riêng của hệ thống.','/assets/services/skyjoy-logo.png','/services/skyjoy',9000,'{"heading":"SkyJoy · Tích điểm, đổi niềm vui","banners":[{"image":"/assets/services/skyjoy-banner.jpg"},{"image":"/assets/services/skyjoy-banner-2.jpg"}],"benefits":[{"icon":"Users","title":"Chương trình khách hàng thân thiết","description":"Tài khoản, hạng hội viên và lịch sử giao dịch trong hệ thống nội bộ."},{"icon":"Coins","title":"Chi tiêu, nhận điểm thưởng","description":"Tích điểm từ vé, dịch vụ và đơn hàng đã thanh toán theo quy tắc nội bộ."},{"icon":"Gift","title":"Đổi điểm lấy voucher","description":"Dùng điểm nội bộ để nhận voucher và thanh toán chuyến bay demo."},{"icon":"Wallet","title":"Ví điểm của bạn","description":"Theo dõi số dư và các lượt cộng, trừ điểm trong tài khoản."}],"provider":"GalaxyJoy","source":"https://skyjoy.vietjetair.com/"}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','e-Voucher','Voucher nội bộ và nội dung đối tác đang chờ tích hợp.','/assets/evoucher/logo.svg','/services/voucher',9000,'{"values":[100000,200000,500000,1000000,2000000],"banners":[{"image":"/assets/evoucher/hero-menas.jpg","label":"Ưu đãi e-Voucher Menas","target":"#evoucher-gratitude"},{"image":"/assets/evoucher/hero-guide.jpg","label":"Hướng dẫn sử dụng e-Voucher","target":"#evoucher-terms"},{"image":"/assets/evoucher/hero-combo.jpg","label":"Combo vé máy bay và khách sạn","target":"#evoucher-combos"}],"combos":[{"name":"TPHCM - Nha Trang | 3N2D Vinpearl Empire Nha Trang","image":"/assets/evoucher/hotel-hoi-an.png","available":false},{"name":"TPHCM - Nha Trang | 3N2D Vinpearl Beachfront Nha Trang","image":"/assets/evoucher/hotel-beachfront.png","available":false},{"name":"TPHCM - Nha Trang | 3N2D Vinpearl Hòn Tằm Nha Trang","image":"/assets/evoucher/hotel-hon-tam.png","available":false},{"name":"Hà Nội - Đà Nẵng | 3N2D Vinpearl Resort & Golf Nam Hội An","image":"/assets/evoucher/hotel-hoi-an.png","available":false},{"name":"TPHCM - Đà Nẵng | 3N2D Vinpearl Resort & Golf Nam Hội An","image":"/assets/evoucher/hotel-hoi-an.png","available":false},{"name":"TPHCM - Phú Quốc | 3N2D Vinpearl Resort & Spa Phú Quốc","image":"/assets/evoucher/hotel-phu-quoc.png","available":false},{"name":"TPHCM - Nha Trang | 3N2D Vinpearl Resort Nha Trang","image":"/assets/evoucher/hotel-nha-trang.png","available":false},{"name":"Hải Phòng - Nha Trang | 3N2D Vinpearl Empire Nha Trang","image":"/assets/evoucher/hotel-empire.png","available":false}],"welcome":[{"name":"Ưu đãi độc quyền cho Hiệp hội Học giả & Chuyên gia Việt Nam - Australia","image":"/assets/evoucher/welcome.jpg","available":false}],"gratitude":[{"name":"e-Voucher Menas cho khách nối chuyến Quốc nội - Quốc tế tại SGN","image":"/assets/evoucher/menas-300.jpg","available":false},{"name":"e-Voucher Menas cho khách nối chuyến Quốc tế - Quốc tế tại SGN","image":"/assets/evoucher/menas-500.jpg","available":false}]}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','SkyShop','Danh mục và giá nội bộ được cung cấp từ máy chủ.','/assets/skyshop/hero.jpg','/services/skyshop',9000,'{"mobileImage":"/assets/skyshop/hero-mobile.jpg","categories":[{"code":"INSURANCE","title":"Bảo hiểm Travel Safe","image":"/assets/skyshop/category-insurance.png"},{"code":"MEAL","title":"Hotmeal","image":"/assets/skyshop/category-meal.png"},{"code":"BAGGAGE","title":"Hành lý ký gửi","image":"/assets/skyshop/category-baggage.png"},{"code":"ESIM","title":"eSIM","image":"/assets/skyshop/category-esim.jpg"},{"code":"TAXI","title":"Taxi","image":"/assets/skyshop/category-taxi.jpg"},{"code":"SHOP","title":"Quà lưu niệm","image":null}],"serviceImages":{"INSURANCE":"/assets/skyshop/insurance.jpg","BAG20":"/assets/skyshop/baggage-20.jpg","BAG30":"/assets/skyshop/baggage-30.jpg","MEAL_RICE":"/assets/skyshop/meal.jpg","MEAL_VEG":"/assets/skyshop/meal-vegetarian.jpg"}}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Trang chủ','Nội dung trang chủ được quản lý trên máy chủ.','/assets/reference/logo.svg','/',9000,'{"quick":[{"title":"Đặt chuyến bay","target":"/","image":"/assets/reference/quick-0.svg"},{"title":"Mua hành lý, suất ăn, chọn chỗ","target":"/my-booking","image":"/assets/reference/quick-1.svg"},{"title":"Ưu tiên làm thủ tục nhanh","target":"/services/priority","image":"/assets/reference/quick-2.svg"},{"title":"Hàng miễn thuế","target":"/services/skyshop","image":"/assets/reference/quick-3.svg"},{"title":"Bảo hiểm","target":"/services/insurance","image":"/assets/reference/quick-4.svg"},{"title":"Vietjet e-Voucher","target":"/services/voucher","image":"/assets/reference/quick-5.png"}],"informationBanners":[{"image":"/assets/reference/travel-advice.jpg","title":"KHUYẾN CÁO DI CHUYỂN","target":"/services/travel-advice"},{"image":"/assets/reference/group-travel.jpg","title":"BAY THEO ĐOÀN","target":"/services/groups"}],"statsTitleImage":"/assets/reference/stats-title.png","statsFooterImage":"/assets/reference/fly-green.png","products":[["Đặt vé","/"],["Skyshop","/services/skyshop"],["Khách sạn","/services/hotels"],["E-Voucher","/services/voucher"],["E-Sim","/services/esim"],["E-Visa","/services/visa"],["Mua ngoại tệ","/services/currency"],["Bảo hiểm","/services/insurance"],["SkyJoy","/services/skyjoy"]],"notices":["[BẢN MÔ PHỎNG ĐỘC LẬP] Đặt vé và thanh toán demo — không phải website chính thức của Vietjet.","Khám phá hành trình demo · Dùng mã DEMO10 giảm 10%, tối đa 200.000 đ.","Check-in demo mở 30 ngày và đóng 1 giờ trước khởi hành."],"footerGroups":[["Để có chuyến bay tốt đẹp",["Điều lệ vận chuyển","Điều kiện vé","Vietjet e-Voucher","Phí và lệ phí","Giấy tờ tùy thân","Quy định hành lý","Thông tin nối chuyến","Kênh thanh toán","Hóa đơn VAT","Hướng dẫn làm thủ tục chuyến bay"]],["Mua hành lý, suất ăn, chọn chỗ ngồi và hơn thế nữa...",["Chọn chỗ ngồi ưu tiên","Mua trước hành lý","Đặt trước suất ăn","Hàng miễn thuế","Quà lưu niệm","Giải trí","Dịch vụ đặc biệt"]],["Dịch vụ cao cấp",["Hạng vé Business","Hạng vé SkyBoss","Phòng chờ sang trọng","Về Vietjet","Giới thiệu dự án","Tin tức và khuyến mại","Cẩm nang du lịch"]],["Trung tâm phục vụ Khách hàng",["Hỗ trợ","Liên hệ","Mua vé ở đâu?","Phòng bán vé","Đại lý bán vé","Tìm vật phẩm bỏ quên"]],["Chính sách",["Chính sách quyền riêng tư","Chính sách sử dụng Cookies","Dịch vụ hàng hóa","Quy trình đổi, hoàn, hủy vé","Điều kiện bản demo"]]],"footerTargets":{"Vietjet e-Voucher":"/services/voucher","Chọn chỗ ngồi ưu tiên":"/my-booking","Mua trước hành lý":"/my-booking","Đặt trước suất ăn":"/my-booking","Hàng miễn thuế":"/services/skyshop","Quà lưu niệm":"/services/skyshop","Hướng dẫn làm thủ tục chuyến bay":"/check-in","Quy trình đổi, hoàn, hủy vé":"/my-booking","Chính sách quyền riêng tư":"/services/privacy","Chính sách sử dụng Cookies":"/services/cookies","Tin tức và khuyến mại":"/services/promotions","Quy định hành lý":"/services/faq#baggage","Điều kiện vé":"/services/faq#booking","Điều lệ vận chuyển":"/services/booking","Phí và lệ phí":"/services/faq#booking","Thông tin nối chuyến":"/services/multi-city","Dịch vụ hàng hóa":"/services/cargo","Giới thiệu dự án":"/services/booking","Điều kiện bản demo":"/services/booking","Hạng vé Business":"/","Hạng vé SkyBoss":"/"},"awards":[{"title":"Hàng không chi phí thấp","image":"/assets/reference/award-0.png"},{"title":"Doanh nghiệp ngành hàng không","image":"/assets/reference/award-1.png"},{"title":"Top công ty niêm yết","image":"/assets/reference/award-2.png"},{"title":"Thương hiệu Châu Á","image":"/assets/reference/award-3.png"},{"title":"Môi trường làm việc","image":"/assets/reference/award-4.png"},{"title":"Phát triển bền vững","image":"/assets/reference/award-5.png"}]}'::jsonb);
