INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Ưu tiên làm thủ tục nhanh','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/priority',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Thanh toán giả lập','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/payment',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Hướng dẫn đặt vé','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/booking',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Chọn chỗ ngồi','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/seats',9000,'{}'::jsonb);
