INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Câu hỏi thường gặp','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/faq',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Quyền riêng tư trong bản demo','Website lưu bản nháp và token truy cập trong sessionStorage trên trình duyệt. Booking demo được lưu PostgreSQL. Không dùng công cụ theo dõi quảng cáo. Chỉ nhập dữ liệu giả để trải nghiệm.','','/services/privacy',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Chính sách cookie','Website lưu bản nháp và token truy cập trong sessionStorage trên trình duyệt. Booking demo được lưu PostgreSQL. Không dùng công cụ theo dõi quảng cáo. Chỉ nhập dữ liệu giả để trải nghiệm.','','/services/cookies',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Kết nối mạng xã hội','Dịch vụ đối tác này được giới thiệu để tái hiện điều hướng website tham chiếu. Bản demo chưa tích hợp đối tác và không nhận giao dịch cho dịch vụ này.','','/services/social',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Săn vé giá rẻ','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/promotions',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Ngôn ngữ trong demo','Bản demo hỗ trợ tiếng Việt và tiếng Anh.','','/services/language',9000,'{}'::jsonb);
INSERT INTO content_items(category,title,description,image,target,sort_order,details) VALUES ('PAGE','Chuẩn bị cho chuyến bay','Bạn có thể tìm chuyến bay, chọn hạng vé, điền dữ liệu hành khách mẫu, chọn ghế và dịch vụ, sau đó thanh toán giả lập. Tra cứu booking bằng mã đặt chỗ và tên hành khách. Check-in demo chỉ áp dụng cho booking đã xác nhận trong thời gian cấu hình.','','/services/travel-advice',9000,'{}'::jsonb);
